<template><div class="page"><div class="page-header"><h2>全模块单据查询</h2></div><el-card shadow="never"><el-table :data="items" v-loading="loading" stripe size="small" highlight-current-row @row-click="open"><el-table-column prop="billid" label="单据号" width="120"/><el-table-column prop="bill_type" label="单据类型" width="120"/><el-table-column label="客户" width="90"><template #default="{row}">{{ custCard(row.custcd) }}</template></el-table-column><el-table-column prop="gendate" label="日期" width="100"/><el-table-column label="操作员" width="80"><template #default="{row}">{{ userName(row.opercd) }}</template></el-table-column><el-table-column prop="memo" label="备注" min-width="150" show-overflow-tooltip/></el-table><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card></div></template>
<script setup lang="ts">import {ref,onMounted} from 'vue';import AppPagination from '@/components/common/AppPagination.vue';import {useUserNames} from '@/composables/useUserNames';import {useCustomerCards} from '@/composables/useCustomerCards';import request from '@/api/request'
const{userName}=useUserNames();const{custCard}=useCustomerCards()
const items=ref<Record<string,unknown>[]>([]);const loading=ref(false);const page=ref(1);const perPage=ref(20);const total=ref(0)
onMounted(async()=>{loading.value=true;try{const res=await request.get('/transactions/bills',{params:{page:String(page.value),per_page:String(perPage.value)}});items.value=res.data.items||[];total.value=res.data.total||0}catch{}finally{loading.value=false}})
function open(_row:Record<string,unknown>){}</script>
<style scoped>.page{padding:0}.page-header{display:flex;justify-content:space-between;margin-bottom:16px}.page-header h2{font-size:18px;font-weight:600;margin:0}</style>
